mapper.select:
SELECT
    q.id            AS question_id,
    q.outline_id    AS outline_id,
    q.difficulty    AS difficulty,
    MAX(r.answered_at) AS last_answered_at
FROM rk_question q
LEFT JOIN user_answer_record r
       ON r.question_id = q.id
      AND r.user_id = #{userId}
      AND r.subject_id = #{subjectId}
WHERE q.subject_id = #{subjectId}
  AND q.question_type = #{questionType}
  AND q.status = 'PUBLISHED'
GROUP BY q.id, q.outline_id, q.difficulty
LIMIT #{limit}

SELECT COUNT(*)
FROM rk_question q
WHERE q.subject_id = #{subjectId}
  AND q.question_type = #{questionType}
  AND q.status = 'PUBLISHED'
